import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Consider a real-valued function f satisfying both reflection and translation invariances: for every real x, f(x) = f(c_i - x) for each i = 1, 2, ..., {num_reflections}, where the reflection centers are {reflection_centers}, and additionally f(x) = f(x + p_j) for each j = 1, 2, ..., {num_translations}, where the translation steps are {translation_steps}. What is the largest possible number of distinct values among the list f(0), f(1), ..., f({n_max})?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Helper functions
def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)
def gcd_list(lst):
    g = 0
    for x in lst:
        g = gcd(g, x)
    return g
# Randomized construction ensuring nontrivial structure
attempts = 0
while True:
    attempts += 1
    if attempts > 100:
        # Fallback to a fixed valid instance if randomness fails repeatedly
        D = 352
        num_reflections = 4
        num_translations = 2
        c1 = 398
        k_list = [1, 2, 3]
        t_list = [1, 4]
    else:
        # Choose a target base period D (moderate size for robustness)
        D = rng.randint(120, 600)
        # Ensure multiple reflections and at least one translation
        num_reflections = rng.randint(4, 7)
        num_translations = rng.randint(1, 3)
        # Choose base center c1 with varied parity
        c1 = rng.randint(100, 5000)
        # Build multipliers for differences and translations
        k_list = [rng.randint(1, 9) for _ in range(num_reflections - 1)]
        t_list = [rng.randint(1, 9) for _ in range(num_translations)]
        # Force gcd of multipliers to be 1 to make the induced gcd exactly D
        if gcd_list(k_list + t_list) != 1:
            if rng.random() < 0.5 and len(k_list) > 0:
                k_list[rng.randrange(len(k_list))] = 1
            else:
                t_list[rng.randrange(len(t_list))] = 1
            if gcd_list(k_list + t_list) != 1:
                if len(k_list) > 0:
                    k_list[0] = 1
                if len(t_list) > 0:
                    t_list[0] = 1
    # Build centers and steps
    centers_list = [c1] + [c1 + D * ki for ki in k_list]
    steps_list = [D * tj for tj in t_list]
    # Compute actual gcd from constructed data
    diffs = [abs(ci - c1) for ci in centers_list[1:]]
    d_actual = gcd_list(diffs + steps_list)
    # Choose n_max so that the interval length L >= d_actual for clean orbit coverage
    L = rng.randint(d_actual, d_actual + rng.randint(d_actual // 2 if d_actual // 2 > 0 else 1, 2 * d_actual))
    n_max = L - 1
    # Validate difficulty and nontriviality
    if d_actual >= 10 and num_reflections >= 4 and L >= d_actual:
        # Prepare display strings
        reflection_centers_str = ", ".join(str(x) for x in centers_list)
        translation_steps_str = ", ".join(str(x) for x in steps_list)
        return {
            'num_reflections': num_reflections,
            'num_translations': num_translations,
            'reflection_centers': reflection_centers_str,
            'translation_steps': translation_steps_str,
            'n_max': n_max,
            # Extra data for verifier
            'centers_list': centers_list,
            'steps_list': steps_list
        }
    # else retry

    def verifier(assign):
# Validate structure
try:
    num_reflections = int(assign.get('num_reflections'))
    num_translations = int(assign.get('num_translations'))
    n_max = int(assign.get('n_max'))
    centers_list = assign.get('centers_list')
    steps_list = assign.get('steps_list')
    if centers_list is None or steps_list is None:
        # Try to parse strings if lists weren't provided
        rc = assign.get('reflection_centers', '')
        ts = assign.get('translation_steps', '')
        centers_list = [int(x.strip()) for x in rc.split(',') if x.strip()]
        steps_list = [int(x.strip()) for x in ts.split(',') if x.strip()]
    # Basic checks
    if not isinstance(centers_list, list) or not isinstance(steps_list, list):
        # Invalid types
        return (False, None)
    if len(centers_list) != num_reflections:
        # mismatch reflection count
        return (False, None)
    if len(steps_list) != num_translations:
        # mismatch translation count
        return (False, None)
    if num_reflections < 1 or num_translations < 1 or n_max < 0:
        return (False, None)
    # Helper gcd
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return abs(a)
    def gcd_list(lst):
        g = 0
        for x in lst:
            g = gcd(g, x)
        return g
    # Compute the induced fundamental period d from differences and translation steps
    c1 = centers_list[0]
    diffs = [abs(ci - c1) for ci in centers_list[1:]]
    S = diffs + steps_list
    # Domain validation: ensure nontrivial constraints
    d = gcd_list(S)
    if d <= 0:
        # invalid; requires at least one positive constraint
        return (False, None)
    # Enforce difficulty: enough reflections and coverage of all residues
    if num_reflections < 4:
        return (False, None)
    if d < 10:
        return (False, None)
    L = n_max + 1
    if L < d:
        # We require full residue coverage for difficulty; generator should avoid this
        return (False, None)
    # Count distinct orbits among residues modulo d present in 0..n_max under r -> -r + c1 (mod d)
    c_mod = c1 % d
    R = set(i % d for i in range(L))
    visited = set()
    count = 0
    for r in list(R):
        if r in visited:
            continue
        s = (c_mod - r) % d
        if s in R:
            count += 1
            visited.add(r)
            visited.add(s)
        else:
            count += 1
            visited.add(r)
    # The above counts fixed points automatically when s == r
    answer = count
    return True, answer
except Exception:
    # Any parsing/computation error
    return (False, None)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

